  Delay3_lowered_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        Delay3_delOut <= '0';
      ELSIF enb = '1' THEN
        Delay3_delOut <= Delay3_ectrl;
      END IF;
    END IF;
  END PROCESS Delay3_lowered_process;


  Delay3_bypass_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        Delay3_last_value <= '0';
      ELSIF enb = '1' THEN
        Delay3_last_value <= Delay3_out1;
      END IF;
    END IF;
  END PROCESS Delay3_bypass_process;


  
  Delay3_out1 <= Delay3_last_value WHEN Delay11_out1 = '0' ELSE
      Delay3_delOut;

  PH2 <=  NOT in_data_PH2;

  
  Delay4_ectrl <= Delay4_delOut WHEN Delay11_out1 = '0' ELSE
      PH2;

  Delay4_lowered_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        Delay4_delOut <= '0';
      ELSIF enb = '1' THEN
        Delay4_delOut <= Delay4_ectrl;
      END IF;
    END IF;
  END PROCESS Delay4_lowered_process;


  Delay4_bypass_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        Delay4_last_value <= '0';
      ELSIF enb = '1' THEN
        Delay4_last_value <= Delay4_out1;
      END IF;
    END IF;
  END PROCESS Delay4_bypass_process;


  
  Delay4_out1 <= Delay4_last_value WHEN Delay11_out1 = '0' ELSE
      Delay4_delOut;

  PH3 <=  NOT in_data_PH3;

  
  Delay5_ectrl <= Delay5_delOut WHEN Delay11_out1 = '0' ELSE
      PH3;

  Delay5_lowered_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        Delay5_delOut <= '0';
      ELSIF enb = '1' THEN
        Delay5_delOut <= Delay5_ectrl;
      END IF;
    END IF;
  END PROCESS Delay5_lowered_process;


  Delay5_bypass_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        Delay5_last_value <= '0';
      ELSIF enb = '1' THEN
        Delay5_last_value <= Delay5_out1;
      END IF;
    END IF;
  END PROCESS Delay5_bypass_process;


  
  Delay5_out1 <= Delay5_last_value WHEN Delay11_out1 = '0' ELSE
      Delay5_delOut;

  PH4 <=  NOT in_data_PH4;

  
  Delay6_ectrl <= Delay6_delOut WHEN Delay11_out1 = '0' ELSE
      PH4;

  Delay6_lowered_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        Delay6_delOut <= '0';
      ELSIF enb = '1' THEN
        Delay6_delOut <= Delay6_ectrl;
      END IF;
    END IF;
  END PROCESS Delay6_lowered_process;


  Delay6_bypass_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        Delay6_last_value <= '0';
      ELSIF enb = '1' THEN
        Delay6_last_value <= Delay6_out1;
      END IF;
    END IF;
  END PROCESS Delay6_bypass_process;


  
  Delay6_out1 <= Delay6_last_value WHEN Delay11_out1 = '0' ELSE
      Delay6_delOut;

  Mux_out1(0) <= Delay2_out1;
  Mux_out1(1) <= Delay3_out1;
  Mux_out1(2) <= Delay4_out1;
  Mux_out1(3) <= Delay5_out1;
  Mux_out1(4) <= Delay6_out1;

  AND_out1 <= switch_cont_disc AND Subsystem1_reset;

  enb_1 <= clk_enable;

  u_For_Each_Subsystem_gen: FOR k IN 0 TO 4 GENERATE
    u_For_Each_Subsystem : uz_JL_SigmaDelta_Interface_src_For_Each_Subsystem
      PORT MAP( clk => clk,
                reset_x => reset_x,
                enb => enb_1,
                clk_fast => Delay11_out1,
                clk_slow => gen_slow_clk_filt_slow_clk,
                data_in => Mux_out1(k),
                reset => AND_out1,
                data_out => For_Each_Subsystem_data_out(k)  -- int32
                );
  END GENERATE;

  outputgen: FOR k IN 0 TO 4 GENERATE
    For_Each_Subsystem_data_out_signed(k) <= signed(For_Each_Subsystem_data_out(k));
  END GENERATE;

  
  Delay1_ectrl <= Delay1_delOut WHEN Subsystem1_Out1 = '0' ELSE
      For_Each_Subsystem_data_out_signed;

  Delay1_lowered_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        Delay1_delOut <= (OTHERS => to_signed(0, 32));
      ELSIF enb = '1' THEN
        Delay1_delOut <= Delay1_ectrl;
      END IF;
    END IF;
  END PROCESS Delay1_lowered_process;


  Delay1_bypass_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        Delay1_last_value <= (OTHERS => to_signed(0, 32));
      ELSIF enb = '1' THEN
        Delay1_last_value <= Delay1_out1;
      END IF;
    END IF;
  END PROCESS Delay1_bypass_process;


  
  Delay1_out1 <= Delay1_last_value WHEN Subsystem1_Out1 = '0' ELSE
      Delay1_delOut;

  
  Switch_out1 <= For_Each_Subsystem_data_out_signed WHEN switch_cont_disc = '0' ELSE
      Delay1_out1;

  data_out_ps_0 <= std_logic_vector(Switch_out1(0));

  data_out_ps_1 <= std_logic_vector(Switch_out1(1));

  data_out_ps_2 <= std_logic_vector(Switch_out1(2));

  data_out_ps_3 <= std_logic_vector(Switch_out1(3));

  data_out_ps_4 <= std_logic_vector(Switch_out1(4));

  out_clk_ads <= Switch1_out1;

  data_raw_U <= Delay2_out1;

  data_raw_PH1 <= Delay3_out1;

  data_raw_PH2 <= Delay4_out1;

  data_raw_PH3 <= Delay5_out1;

  data_raw_PH4 <= Delay6_out1;

  fast_clk_filt <= Subsystem_filt_fast_clk;

  Data_valid <= Subsystem1_data_valid;

  reset <= AND_out1;

  data_valid_pl <= Subsystem1_data_valid;

  filt_slow_clk <= gen_slow_clk_filt_slow_clk;

  ce_out <= clk_enable;

  data_valid_cnt <= Subsystem1_data_valid_cnt;

END rtl;

